import {
  accountRefSchema,
  assetRefSchema,
  type ChainEvent,
  chainRefSchema,
  isTxHash,
  type SettlementCheck,
  type TxHash,
} from "@binference/plugin-sdk";

// Logs of real Across transactions, read on 2026-11-01 from BNB Smart Chain's and Arbitrum One's
// public RPCs, each as the delivery reader gives it: the SpokePools' own logs, and one token
// transfer that is no settlement of anyone's. A fill on Arbitrum One of 288.148284 USDC for deposit
// 1264861 from BSC, that deposit, a deposit of ETH to Ethereum that Across refunded, and the
// relayer refund leaves that paid it back with other addresses' refunds of three tokens.

// The selector of the SpokePool's `FilledRelay` event.
const filledRelayTopic = "0x44b559f101f8fbcc8a0ea43fa91a05a729a5ea6e14a7c75aa750374690137208";

type RecordedLog = readonly [emitter: string, topics: readonly string[], data: string];

function eventsOn(chain: string, logs: readonly RecordedLog[]): readonly ChainEvent[] {
  return logs.map(([emitter, topics, data]) => ({
    emitter: accountRefSchema.parse(`${chain}:${emitter}`),
    topics,
    data,
  }));
}

