function hashOf(text: string): TxHash {
  if (!isTxHash(text)) {
    throw new Error("Expected a transaction hash.");
  }
  return text;
}

const bsc = chainRefSchema.parse("eip155:56");
const arbitrum = chainRefSchema.parse("eip155:42161");

// Deposit 1264861 of 288.504212627345096261 USDC from BSC, filled on Arbitrum One with 288.148284.
/** The recorded fill as a host asks Across to match it, with its deposit. */
export const recordedFillCheck: SettlementCheck = {
  kind: "fill",
  deposit: {
    ref: { chain: bsc, hash: hashOf(`0x${"0f".repeat(32)}`) },
    events: recordedFillDepositEvents,
  },
  settlement: {
    ref: { chain: arbitrum, hash: hashOf(`0x${"f8".repeat(32)}`) },
    events: recordedFillEvents,
  },
  wallet: accountRefSchema.parse(`${bsc}:0x144c5fb302dbaa789fc59bbec301169eaa56c5fc`),
  amountIn: {
    asset: assetRefSchema.parse(`${bsc}/erc20:0x8AC76a51cc950d9822D68b83fE1Ad97B32Cd580d`),
    base: 288_504_212_627_345_096_261n,
  },
  recipient: accountRefSchema.parse(`${arbitrum}:0x168E0c5AE6B259883D878C89C042ad6347F8ba85`),
  minOut: {
    asset: assetRefSchema.parse(`${arbitrum}/erc20:0xaf88d065e77c8cC2239327C5EDb3A432268e5831`),
    base: 288_000_000n,
  },
};

// Deposit 1269971 of 0.059462062799438419 ETH from BSC to Ethereum, refunded in a relayer refund
// leaf that also paid five other addresses.
/** The recorded refund as a host asks Across to match it, with its deposit. */
export const recordedRefundCheck: SettlementCheck = {
  kind: "refund",
  deposit: {
    ref: { chain: bsc, hash: hashOf(`0x${"42".repeat(32)}`) },
    events: recordedRefundDepositEvents,
  },
  settlement: {
    ref: { chain: bsc, hash: hashOf(`0x${"81".repeat(32)}`) },
    events: recordedRefundEvents,
  },
  wallet: accountRefSchema.parse(`${bsc}:0x80358c5b8f9b2cc27147a1e0f2a6c9a30eb2c397`),
  amountIn: {
    asset: assetRefSchema.parse(`${bsc}/erc20:0x2170Ed0880ac9A755fd29B2688956BD959F933F8`),
    base: 59_462_062_799_438_419n,
  },
  recipient: accountRefSchema.parse("eip155:1:0x60ac95ec1153aa8199751917ede25d0ca49a36e2"),
  minOut: {
    asset: assetRefSchema.parse("eip155:1/erc20:0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2"),
    base: 1n,
  },
};

/**
 * The recorded fill's check with the SpokePool's fill event left out: a bare transfer of the
 * recipient's token, which no deposit owns.
 */
export const recordedBareTransferCheck: SettlementCheck = {
  ...recordedFillCheck,
  settlement: {
    ...recordedFillCheck.settlement,
    events: recordedFillEvents.filter((event) => event.topics[0] !== filledRelayTopic),
  },
};
